-- ClientVault database: run this whole file once in MySQL Workbench
DROP DATABASE IF EXISTS clientvault;
CREATE DATABASE clientvault;
USE clientvault;

CREATE TABLE clients (
  client_id VARCHAR(10) PRIMARY KEY,
  full_name VARCHAR(100) NOT NULL,
  phone VARCHAR(20),
  email VARCHAR(100),
  address VARCHAR(200),
  reg_date DATE,
  client_type VARCHAR(20),
  status VARCHAR(20)
);


SELECT COUNT(*) AS total_clients FROM clients;
